class Ui:
    handlers: Array[fn()] = []

    fn fire():
        for ref mut h in this.handlers:   # [CLO-18]: the holder reached through a name that may change it
            h()                            # [CLO-10]: "copies the two words out before the arguments are given"  <-- where does `calls += 1` land?

@noalloc
fn counter() -> fn():
    n = 0
    return fn() owns n: n += 1           # <-- state is one `int`: in the state word (no Alloc, compiles) or in a block (Alloc, E4001)?

fn main():
    ui = Ui()
    calls = 0
    ui.handlers.push(owns fn() copy of calls: calls += 1)
    ui.fire()
    ui.fire()                            # the handler's own `calls` is 2 with a block, 1 for ever with an inline word copied out and never written back

fn maybe(xs: Array[int], c: bool) -> int:
    if c:
        take(owns xs)          # [OWN-3]: "tracked with a hidden drop flag": a store here and a test at the function's end, no row
    return 1

static CFG: Map[String, int] = load()   # [STA-3]: "runs once, on first access ... the first access blocks": a test per access, no row

fn send(owns names: Names):
    h = thread.spawn(owns fn() owns names: names.items.len())   # [THR-2]: "reads the object's weak count, one compare", and "its contents move to a new block": an allocation [PHIL-2]'s list lacks, no row

from std.mem import assert_disjoint

@no_alias_checks
fn mix(ref mut xs: Array[float]):
    a, b = xs.as_mut_span().split_at(2)
    assert_disjoint(a, b)          # <-- [DSJ-5]: no compare "in which case" the compiler knows them apart; [EFF-15]: the proofs that count are four, and this is none of them: E4030 or not?
    println(a.len(), b.len())

fn main():
    big = 2 ** 70            # <-- [TYP-8]: "panics with `integer overflow in '**'`"; [LEX-16]: E2010 is for a literal, and this is an expression; [TYP-30] decides a constant negative exponent when compiling and says nothing of a constant overflow
    println(big)

fn share(owns xs: Array[int]):
    other = shares xs          # <-- [RC-1]: "a local of this function that owns its value ... made in a block of its own from the line that made it": a parameter is made by no line here; E2122 names "a plain parameter" only
    println(other.len(), xs.len())
